348	    private PaymentInfo calculatePayment(CheckoutRequest request, BigDecimal orderTotal) {
349	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
350	
351	        BigDecimal adjustment;
352	        BigDecimal finalTotal;
353	        BigDecimal installmentAmount;
354	
355	        switch (request.getPaymentMethod()) {
356	            case PIX -> {
