221	                }
222	                return new ShippingInfo(new BigDecimal("18.00"), 0);
223	            }
224	            case ECONOMY, EXPRESS -> {
225	                String service = request.getShippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
226	
227	                TransLogService.QuoteResult quote = transLogService.getQuote(
228	                        request.getZipCode(), totalWeight, service);
