271	@Service
272	public class TransLogService {
273	
274	    private final String translogUrl;
275	    private final RestClient restClient;
276	
277	    public TransLogService(
278	            @Value("${translog.url}") String translogUrl,
279	            @Value("${translog.timeout.seconds}") int timeoutSeconds) {
280	        this.translogUrl = translogUrl;
281	        this.restClient = RestClient.builder()
282	                .baseUrl(translogUrl)
283	                .build();
284	    }
