286	    public QuoteResult getQuote(String zipCode, BigDecimal weightKg, String service) {
287	        try {
288	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
289	
290	            String url = String.format("/v2/quote?zip=%s&weight_g=%d&service=%s",
291	                    zipCode, weightGrams, service);
292	
293	            TransLogResponse response = restClient.get()
294	                    .uri(url)
295	                    .retrieve()
296	                    .body(TransLogResponse.class);
297	
298	            if (response == null) {
299	                return QuoteResult.unavailable();
300	            }
301	
302	            if (response.error != null) {
303	                if ("ZIP_NOT_SERVED".equals(response.error)) {
304	                    return QuoteResult.notServed();
305	                }
306	                return QuoteResult.unavailable();
307	            }
308	
309	            if (response.priceCents == null || response.etaHours == null) {
310	                return QuoteResult.unavailable();
311	            }
312	
313	            BigDecimal price = new BigDecimal(response.priceCents)
314	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
315	
316	            int days = (int) Math.ceil(response.etaHours / 24.0);
317	
318	            return QuoteResult.success(price, days);
319	
320	        } catch (Exception e) {
321	            return QuoteResult.unavailable();
322	        }
323	    }
324	
325	    public static class QuoteResult {
326	        private final boolean available;
327	        private final boolean served;
328	        private final BigDecimal price;
329	        private final int days;
330	
331	        private QuoteResult(boolean available, boolean served, BigDecimal price, int days) {
332	            this.available = available;
333	            this.served = served;
334	            this.price = price;
335	            this.days = days;
336	        }
337	
338	        public static QuoteResult success(BigDecimal price, int days) {
339	            return new QuoteResult(true, true, price, days);
340	        }
341	
342	        public static QuoteResult notServed() {
343	            return new QuoteResult(true, false, null, 0);
344	        }
345	
346	        public static QuoteResult unavailable() {
347	            return new QuoteResult(false, false, null, 0);
348	        }
349	
350	        public boolean isAvailable() {
351	            return available;
352	        }
353	
354	        public boolean isServed() {
355	            return served;
356	        }
357	
358	        public BigDecimal getPrice() {
359	            return price;
360	        }
361	
362	        public int getDays() {
363	            return days;
364	        }
365	    }
366	
367	    private static class TransLogResponse {
368	        @JsonProperty("price_cents")
369	        private Integer priceCents;
370	
371	        @JsonProperty("eta_hours")
372	        private Integer etaHours;
373	
374	        private String error;
375	
376	        public Integer getPriceCents() {
377	            return priceCents;
378	        }
379	
380	        public void setPriceCents(Integer priceCents) {
381	            this.priceCents = priceCents;
382	        }
383	
384	        public Integer getEtaHours() {
385	            return etaHours;
386	        }
387	
388	        public void setEtaHours(Integer etaHours) {
389	            this.etaHours = etaHours;
390	        }
391	
392	        public String getError() {
393	            return error;
394	        }
395	
396	        public void setError(String error) {
397	            this.error = error;
398	        }
399	    }
400	}
